export const LEAD_SCRIPT = "<script>\n    (function(){\n      var form = document.getElementById('leadForm-{{SLUG}}');\n      var status = document.getElementById('leadStatus-{{SLUG}}');\n      var btn = document.getElementById('leadBtn-{{SLUG}}');\n      form.addEventListener('submit', function(e){\n        e.preventDefault();\n        btn.disabled = true; btn.textContent = 'Sending...';\n        var formData = new FormData(form);\n        try{ fetch('/api/leads', { method: 'POST', headers: {'Content-Type':'application/json'}, keepalive: true, body: JSON.stringify({ form: 'firm-profile', name: form.name.value, email: form.email.value, phone: form.phone.value, message: form.message.value, firm: '{{SLUG}}', firmName: '{{NAME}}', botcheck: form.botcheck.checked ? '1' : '', page: location.pathname }) }).catch(function(){}); }catch(_){}\n        fetch('https://api.web3forms.com/submit', {\n          method: 'POST',\n          headers: {'Accept':'application/json'},\n          body: formData\n        }).then(function(r){ return r.json(); }).then(function(data){\n          if(data.success){\n            status.style.color = '#2b3a4c';\n            status.textContent = 'Message sent \\u2014 {{NAME}} will be in touch soon.';\n            form.querySelectorAll('input,textarea,button').forEach(function(el){ el.style.display='none'; });\n          } else {\n            status.style.color = '#e2bd6a';\n            status.textContent = 'Something went wrong. Please try again or call directly.';\n            btn.disabled = false; btn.textContent = 'Send Message';\n          }\n        }).catch(function(){\n          status.style.color = '#e2bd6a';\n          status.textContent = 'Something went wrong. Please try again or call directly.';\n          btn.disabled = false; btn.textContent = 'Send Message';\n        });\n      });\n    })();\n    </script>";
